/* LIMÉRENCE page loading. Source mark: user PNG supplied 2026-10-18, unchanged pixels.
   No navigation interception, minimum display time, dependencies or video waits. */
(() => {
  'use strict';
  if (window.lmPageLoaderInstalled) return;
  window.lmPageLoaderInstalled = true;
  const style = document.createElement('style');
  style.textContent = "html.lm-page-arriving body{visibility:hidden}#lm-page-loader{position:fixed;inset:0;z-index:99990;display:grid;place-items:center;background:#fff;pointer-events:none;animation:lm-loader-safety 5s step-end forwards}#lm-page-loader[hidden]{display:none!important}.lm-loader-mark{width:104px;height:auto;overflow:visible}#lm-page-loader .trace{stroke:#fff;fill:none;stroke-width:24;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:1;stroke-dashoffset:0}#lm-page-loader .dot{fill:#fff;transform-origin:782px 640px}#lm-page-loader .outer{animation:lm-loader-draw 1050ms cubic-bezier(.16,1,.3,1) both}#lm-page-loader .stem{animation:lm-loader-draw 800ms 220ms cubic-bezier(.16,1,.3,1) both}#lm-page-loader .letter{animation:lm-loader-draw 900ms 390ms cubic-bezier(.16,1,.3,1) both}#lm-page-loader .dot{animation:lm-loader-point 260ms 1080ms ease-out both}@keyframes lm-loader-draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}@keyframes lm-loader-point{from{opacity:0;transform:scale(.45)}to{opacity:1;transform:scale(1)}}@keyframes lm-loader-safety{to{visibility:hidden}}@media(prefers-reduced-motion:reduce){#lm-page-loader .trace,#lm-page-loader .dot{animation:none}}";
  document.head.append(style);
  const mark = "<svg class=\"lm-loader-mark\" viewBox=\"475 460 330 360\" aria-hidden=\"true\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs><mask id=\"lm-loader-reveal\" maskUnits=\"userSpaceOnUse\" x=\"470\" y=\"450\" width=\"350\" height=\"370\"><path class=\"trace outer\" pathLength=\"1\" d=\"M772 536 C719 476 657 470 611 488 C541 507 493 571 493 639 C493 725 562 799 650 799 C698 799 740 777 772 743\"/><path class=\"trace stem\" pathLength=\"1\" d=\"M605 544 L605 732 L674 732\"/><path class=\"trace letter\" pathLength=\"1\" d=\"M605 545 L646 545 C692 545 694 612 647 612 L605 612 C645 612 652 631 669 668 C687 711 698 734 716 744\"/><circle class=\"dot\" cx=\"782\" cy=\"640\" r=\"13\"/></mask></defs>\n<image width=\"1280\" height=\"1280\" href=\"data:image/png;base64,\" mask=\"url(#lm-loader-reveal)\"/>\n</svg>";
  let overlay, showTimer, safetyTimer, generation = 0;
  function finish() {
    generation++;
    document.documentElement.classList.remove('lm-page-arriving');
    clearTimeout(showTimer); clearTimeout(safetyTimer);
    if (overlay) { overlay.remove(); overlay = null; }
  }
  function fitViewport() {
    if (!overlay) return;
    // Mobile layout can temporarily overflow while the main stylesheet loads.
    // Centre in the visible screen, not in that enlarged layout viewport.
    const viewport = window.visualViewport;
    const width = viewport?.width || document.documentElement.clientWidth || innerWidth;
    const height = viewport?.height || document.documentElement.clientHeight || innerHeight;
    overlay.style.width = width + 'px';
    overlay.style.height = height + 'px';
    overlay.style.left = (viewport?.offsetLeft || 0) + 'px';
    overlay.style.top = (viewport?.offsetTop || 0) + 'px';
  }
  function start() {
    finish();
    const current = generation;
    safetyTimer = setTimeout(finish, 5000);
    showTimer = setTimeout(() => {
      if (current !== generation || document.hidden) return;
      overlay = document.createElement('div');
      overlay.id = 'lm-page-loader';
      overlay.setAttribute('role', 'status');
      overlay.setAttribute('aria-label', 'Loading page');
      overlay.innerHTML = mark;
      // Body may not exist yet when this early head script reaches the threshold.
      document.documentElement.append(overlay);
      fitViewport();
    }, 180);
    return current;
  }
  const arrival = start();
  // Arm the fail-safe before hiding unstyled content; without JS it stays visible.
  document.documentElement.classList.add('lm-page-arriving');
  function stylesReady() {
    if (generation !== arrival) return;
    const styles = Array.from(document.querySelectorAll('link[data-lm-page-style]'));
    let pending = styles.length;
    if (!pending) { contentReady(); return; }
    styles.forEach(link => {
      let settled = false;
      const done = () => {
        if (settled) return;
        settled = true;
        link.removeEventListener('load', done); link.removeEventListener('error', done);
        link.media = link.dataset.lmPageMedia || 'all';
        if (--pending === 0 && generation === arrival) contentReady();
      };
      link.addEventListener('load', done, {once:true});
      link.addEventListener('error', done, {once:true});
      if (link.dataset.lmPageReady === '1' || link.sheet) done();
    });
  }
  function contentReady() {
    if (generation !== arrival) return;
    // Only visible first-screen images matter. Lazy/offscreen media and movies never gate entry.
    const images = Array.from(document.images).filter(image => {
      const rect = image.getBoundingClientRect();
      return !image.complete && rect.width > 0 && rect.height > 0 &&
        rect.top < innerHeight && rect.bottom > 0 && rect.left < innerWidth && rect.right > 0;
    });
    let pending = images.length;
    if (!pending) { finish(); return; }
    images.forEach(image => {
      const done = () => {
        image.removeEventListener('load', done); image.removeEventListener('error', done);
        if (--pending === 0 && generation === arrival) finish();
      };
      image.addEventListener('load', done, {once: true});
      image.addEventListener('error', done, {once: true});
      if (image.complete) done();
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', stylesReady, {once:true});
  else stylesReady();
  addEventListener('resize', fitViewport);
  window.visualViewport?.addEventListener('resize', fitViewport);
  window.visualViewport?.addEventListener('scroll', fitViewport);
  addEventListener('pageshow', finish);
  addEventListener('pagehide', finish);
  document.addEventListener('visibilitychange', () => { if (document.hidden) finish(); });
  // Any interaction dismisses the visual layer; content and browser navigation are never locked.
  document.addEventListener('pointerdown', finish, true);
  document.addEventListener('keydown', finish, true);
  document.addEventListener('click', event => {
    if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    const link = event.target.closest && event.target.closest('a[href]');
    if (!link || link.hasAttribute('download') || (link.target && link.target !== '_self') ||
        link.closest('[data-no-page-loader]') || link.classList.contains('add_to_cart_button')) return;
    const url = new URL(link.href, location.href);
    if (!/^https?:$/.test(url.protocol) || url.origin !== location.origin ||
        url.searchParams.has('add-to-cart') || url.searchParams.has('remove_item') ||
        (url.pathname === location.pathname && url.search === location.search)) return;
    // Defer until all handlers can cancel a drawer, gallery or other same-page action.
    queueMicrotask(() => { if (!event.defaultPrevented) start(); });
  });
})();
